:{"value":48,"kind":"design","source":"design"},"wall_drop":{"value":9,"kind":"design","source":"design"},"wall_entry_d":{"value":10.2,"kind":"design","source":"design"},"wall_slot_w":{"value":4.9,"kind":"design","source":"design"},"base_t":{"value":3.2,"kind":"design","source":"design"},"front_z":{"value":48,"kind":"design","source":"design"},"rim_gap":{"value":2,"kind":"design","source":"design"},"shell_half_w":{"value":62,"kind":"design","source":"design"},"shell_top":{"value":69,"kind":"design","source":"design"},"shell_bottom":{"value":-110,"kind":"design","source":"design"},"shell_lower_knee":{"value":-90,"kind":"design","source":"design"},"shell_bottom_half_w":{"value":48,"kind":"design","source":"design"},"rim_t":{"value":5,"kind":"design","source":"design"},"usb_bay_w":{"value":88,"kind":"design","source":"design"},"wire_bay_w":{"value":38,"kind":"design","source":"design"},"sled_y":{"value":-64,"kind":"design","source":"design"},"sled_half_pitch":{"value":38,"kind":"design","source":"design"},"sled_bar_w":{"value":8,"kind":"design","source":"design"},"sled_t":{"value":3,"kind":"design","source":"design"},"sled_landing_h":{"value":6.6,"kind":"design","source":"design"},"perf_post_h":{"value":7,"kind":"design","source":"design"},"perf_post_d":{"value":7,"kind":"design","source":"design"}},"parts":[{"id":"rear_box","role":"final","material":"Matte-white PLA","print_orientation":"Broad wall-facing back on bed at z=0; open side and insert bores face up. No supports.","use_orientation":"Against wall, +Y up; wide USB bay at bottom, smaller wire/vent opening at top.","code":"def build(p):
    def profile(w, top, b, knee, bw):
        return [(-w,knee),(-bw,b),(bw,b),(w,knee),(w,top),(-w,top)]
    def poly(points,z,h):
        return cq.Workplane('XY',origin=(0,0,z)).polyline(points).close().extrude(h)
    def box(x,y,z,w,l,h):
        return cq.Workplane('XY',origin=(x,y,z)).box(w,l,h,centered=(True,True,False))
    def cyl(x,y,z,d,h):
        return cq.Workplane('XY',origin=(x,y,z)).circle(d/2).extrude(h)
    a,t,b,k,c,r = p.shell_half_w,p.shell_top,p.shell_bottom,p.shell_lower_knee,p.shell_bottom_half_w,p.rim_t
    f,front = p.base_t,p.front_z
    out = profile(a,t,b,k,c)
    inn = profile(a-r,t-r,b+r,k+2,c-3)
    rim_z = front-p.rim_gap
    w = poly(out,0,rim_z).cut(poly(inn,f,front))
    # Open bays are cut all the way to the open front. The wall-facing floor remains intact.
    w = w.cut(box(0,b+6,f,p.usb_bay_w,54,front))
    w = w.cut(box(0,t,f,p.wire_bay_w,24,front))
    for s in (-1,1):
        for y in (24,-58):
            w = w.union(box(s*(a-r/2),y,rim_z-0.2,r,8,p.rim_gap+0.2))
        x, yh = s*p.wall_pitch/2, p.wall_final_y
        ye = yh-p.wall_drop
        w = w.cut(cyl(x,ye,-0.2,p.wall_entry_d,f+0.4))
        w = w.cut(box(x,(ye+yh)/2,-0.2,p.wall_slot_w,p.wall_drop,f+0.4))
        w = w.cut(cyl(x,yh,-0.2,p.wall_slot_w,f+0.4))
        # PCB tower tapers toward an 8 mm seating land on the PCB back.
        x = s*p.disk_pitch/2
        tower = cq.Workplane('XY',origin=(x,0,f-0.2)).circle(9).workplane(offset=front-f-5.8).circle(6).loft(combine=True)
        cap = cq.Workplane('XY',origin=(x,0,front-6.1)).circle(6).workplane(offset=6.1).circle(4).loft(combine=True)
        w = w.union(tower).union(cap)
        w = w.cut(cyl(x,0,front-p.insert_bore_depth,p.insert_bore,p.insert_bore_depth+0.2))
        for v in (-1,1):
            sx,sy = s*p.sled_half_pitch,p.sled_y+v*p.sled_half_pitch
            seat = f+p.sled_landing_h
            w = w.union(cyl(sx,sy,f-0.2,10,p.sled_landing_h+0.2))
            if v==1:
                w = w.cut(cyl(sx,sy,seat-p.insert_bore_depth,p.insert_bore,p.insert_bore_depth+0.2))
    return w"},{"id":"perf_carrier","role":"final","material":"Matte-white PLA","print_orientation":"Lattice flat on bed at z=0; four perfboard pilots up. No supports.","use_orientation":"Lattice down, perfboard up toward disk. Turn complete carrier as needed so USB points out the bottom bay.","code":"def build(p):
    d,w,t = p.sled_half_pitch,p.sled_bar_w,p.sled_t
    e = p.perf_hole_edge+p.perf_hole_d/2
    a,b = p.perf_width/2-e,p.perf_length/2-e
    def bar(x,y,dx,dy):
        return cq.Workplane('XY',origin=(x,y,0)).box(dx,dy,t,centered=(True,True,False))
    s = bar(0,d,2*d+w,w).union(bar(-d,0,w,2*d+w)).union(bar(0,-d,2*d+w,w)).union(bar(d,0,w,2*d+w))
    for x in (-a,a):
