    return w"},{"id":"perf_carrier","role":"final","material":"Matte-white PLA","print_orientation":"Lattice flat at z=0; posts up, no supports.","use_orientation":"Posts toward LED disk. Rotate in 90-degree increments until USB points out of the lower bay.","code":"def build(p):
